<?php
require_once __DIR__.'/config/database.php';header('Content-Type: application/xml; charset=utf-8');header('Cache-Control: public,max-age=3600');$db=(new Database())->getConnection();$base=rtrim(BASE_URL,'/');$urls=[['loc'=>$base.'/index.php','priority'=>'1.0'],['loc'=>$base.'/products.php','priority'=>'0.9']];if($db){foreach($db->query("SELECT id,updated_at FROM products WHERE approval_status='approved' ORDER BY id")->fetchAll() as $p)$urls[]=['loc'=>$base.'/product-detail.php?id='.(int)$p['id'],'lastmod'=>date('c',strtotime($p['updated_at']??'now')),'priority'=>'0.8'];}echo '<?xml version="1.0" encoding="UTF-8"?>';?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><?php foreach($urls as $url):?><url><loc><?php echo htmlspecialchars($url['loc'],ENT_XML1,'UTF-8');?></loc><?php if(!empty($url['lastmod'])):?><lastmod><?php echo $url['lastmod'];?></lastmod><?php endif;?><priority><?php echo $url['priority'];?></priority></url><?php endforeach;?></urlset>
